	// REPRO: LmdbSailStore#currentStoreSnapshotCoordinates reads the journal mutation stamp through the caller's
	// thread-local read txn without holding the TxnManager read lock. A concurrent commit (TxnManager#deactivate during
	// journal replay, or #reset after every commit and after each independent journal acknowledgement)
	// resets that txn underneath the read; LMDB answers EINVAL and the coordinate read fails although the data is
	// already durable.
	@Test
	void snapshotCoordinateReadMustNotRaceWithConcurrentCommitResettingItsTxn(@TempDir File storeDir) throws Exception {
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,posc").setFrontierEstimatorMode(FrontierEstimatorMode.OFF)
				.setSketchEstimatorEnabled(false);
		LmdbStore store = new LmdbStore(storeDir, config);
		store.init();
		try {
			LmdbSailStore backingStore = store.getBackingStore();
			Field valueStoreField = LmdbSailStore.class.getDeclaredField("valueStore");
			valueStoreField.setAccessible(true);
			ValueStore valueStore = (ValueStore) valueStoreField.get(backingStore);
			IRI subject = F.createIRI("urn:snapshot-race:subject");
			Value object = F.createLiteral("race");
			valueStore.startTransaction(true);
			valueStore.storeValue(subject);
			valueStore.storeValue(RDFS.LABEL);
			valueStore.storeValue(object);
			valueStore.commit();
			Field tripleStoreField = LmdbSailStore.class.getDeclaredField("tripleStore");
			tripleStoreField.setAccessible(true);
			TripleStore originalTripleStore = (TripleStore) tripleStoreField.get(backingStore);
			TripleStore tripleStoreSpy = spy(originalTripleStore);
			tripleStoreField.set(backingStore, tripleStoreSpy);
			try {
				long initialRevision = tripleStoreSpy.getDataRevision();
				long initialStamp = tripleStoreSpy.latestFrontierMutationSequence();
				CountDownLatch stampEntered = new CountDownLatch(1);
				CountDownLatch stampRelease = new CountDownLatch(1);
				CountDownLatch replayEntered = new CountDownLatch(1);
				CountDownLatch replayRelease = new CountDownLatch(1);
				AtomicReference<Thread> coordinateReader = new AtomicReference<>();
				AtomicReference<Long> coordinateStamp = new AtomicReference<>();
				doAnswer(invocation -> {
					if (Thread.currentThread() == coordinateReader.get()) {
						stampEntered.countDown();
						awaitLatch(stampRelease, "the mutation-stamp read to be released");
					}
					Long stamp = (Long) invocation.callRealMethod();
					if (Thread.currentThread() == coordinateReader.get()) {
						coordinateStamp.set(stamp);
					}
					return stamp;
				}).when(tripleStoreSpy).latestFrontierMutationSequence(any(Txn.class));
				doAnswer(invocation -> {
					if (Thread.currentThread() == coordinateReader.get()) {
						stampEntered.countDown();
						awaitLatch(stampRelease, "the mutation-stamp read to be released");
					}
					return invocation.callRealMethod();
				}).when(tripleStoreSpy).latestFrontierMutationSequence();
				AtomicBoolean failFirstCommit = new AtomicBoolean(true);
				AtomicInteger nativeCommitAttempts = new AtomicInteger();
				doAnswer(invocation -> {
					nativeCommitAttempts.incrementAndGet();
					if (failFirstCommit.compareAndSet(true, false)) {
						mdb_txn_abort(invocation.getArgument(0, Long.class));
						return MDB_MAP_FULL;
					}
					replayEntered.countDown();
					awaitLatch(replayRelease, "the retried native commit to be released");
					return invocation.callRealMethod();
				}).when(tripleStoreSpy).commitWriteTransaction(anyLong());
				Method coordinates = LmdbSailStore.class.getDeclaredMethod("currentStoreSnapshotCoordinates");
				coordinates.setAccessible(true);
				AtomicReference<Throwable> readerFailure = new AtomicReference<>();
				Thread reader = new Thread(() -> {
					try {
						coordinates.invoke(backingStore);
					} catch (InvocationTargetException e) {
						readerFailure.set(e.getCause());
					} catch (Throwable failure) {
						readerFailure.set(failure);
					}
				}, "lmdb-snapshot-coordinate-reader");
				coordinateReader.set(reader);
				reader.start();
				assertTrue("reader must pause inside the mutation-stamp read",
						stampEntered.await(10L, TimeUnit.SECONDS));
				boolean readLockHeld = readLockHeldWhileParked(originalTripleStore.getTxnManager());
				// Force a consumed native commit failure, then park the real Sail transaction's retry before
				// publication.
				AtomicReference<Throwable> writerFailure = new AtomicReference<>();
				Thread writer = new Thread(() -> {
					try (SailConnection connection = store.getConnection()) {
						connection.begin(IsolationLevels.SNAPSHOT);
						connection.addStatement(subject, RDFS.LABEL, object);
						connection.commit();
					} catch (Throwable failure) {
						writerFailure.set(failure);
					}
				}, "lmdb-auto-grow-writer");
				writer.start();
				try {
					if (readLockHeld) {
						// a read that holds the read lock legitimately has to finish before the commit can proceed
						stampRelease.countDown();
					}
					assertTrue("writer must reach the retried native commit",
							replayEntered.await(10L, TimeUnit.SECONDS));
					assertEquals("replay must not publish its data revision before native commit", initialRevision,
							tripleStoreSpy.getDataRevision());
					stampRelease.countDown();
					// the read either completes now or legitimately waits for the parked commit to finish
					reader.join(TimeUnit.SECONDS.toMillis(5L));
				} finally {
					replayRelease.countDown();
					stampRelease.countDown();
					writer.join(TimeUnit.SECONDS.toMillis(30L));
					reader.join(TimeUnit.SECONDS.toMillis(30L));
				}
				assertFalse("writer must finish", writer.isAlive());
				assertFalse("reader must finish", reader.isAlive());
				if (writerFailure.get() != null) {
					throw new AssertionError("the concurrent commit failed", writerFailure.get());
				}
				if (readerFailure.get() != null) {
					throw new AssertionError("reading the store snapshot coordinates must not fail because a "
							+ "concurrent commit reset the thread-local read txn underneath the unlocked stamp read",
							readerFailure.get());
				}
				assertEquals("the actual Sail transaction must retry exactly one consumed native commit", 2,
						nativeCommitAttempts.get());
				assertTrue("the final authoritative commit must publish its data revision",
						tripleStoreSpy.getDataRevision() > initialRevision);
				assertEquals("the coordinate reader must retain the pre-commit statement stamp", initialStamp,
						coordinateStamp.get().longValue());
				assertTrue("the final authoritative commit must publish its statement mutation stamp",
						tripleStoreSpy.latestFrontierMutationSequence() > initialStamp);
			} finally {
				tripleStoreField.set(backingStore, originalTripleStore);
			}
		} finally {
			store.shutDown();
		}
	}

	// REINFORCE: with Frontier OFF the learned-sidecar mutation stamp still advances on every commit that changed a
	// statement, and only then: duplicate inserts, namespace-only commits and rollbacks leave it untouched.
	@Test
	void statementMutationStampAdvancesOnlyWithDurableStatementChangesInOffMode(@TempDir File storeDir)
			throws Exception {
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,posc").setFrontierEstimatorMode(FrontierEstimatorMode.OFF)
				.setSketchEstimatorEnabled(false);
		LmdbStore store = new LmdbStore(storeDir, config);
		store.init();
		try {
			LmdbSailStore backingStore = store.getBackingStore();
			Method stamp = LmdbSailStore.class.getDeclaredMethod("statementMutationStamp");
			stamp.setAccessible(true);
			IRI subject = F.createIRI("urn:off-stamp:subject");
			long initial = (long) stamp.invoke(backingStore);
			try (SailConnection connection = store.getConnection()) {
				connection.begin();
				connection.addStatement(subject, RDFS.LABEL, F.createLiteral("one"));
				connection.commit();
			}
			long afterInsert = (long) stamp.invoke(backingStore);
			assertTrue("an inserted statement must advance the stamp", afterInsert > initial);
			try (SailConnection connection = store.getConnection()) {
				connection.begin();
				connection.addStatement(subject, RDFS.LABEL, F.createLiteral("one"));
				connection.commit();
			}
			assertEquals("a duplicate insert must not advance the stamp", afterInsert,
					(long) stamp.invoke(backingStore));
			try (SailConnection connection = store.getConnection()) {
				connection.begin();
				connection.setNamespace("off", "urn:off-stamp:namespace#");
				connection.commit();
			}
			assertEquals("a namespace-only commit must not advance the stamp", afterInsert,
					(long) stamp.invoke(backingStore));
			try (SailConnection connection = store.getConnection()) {
				connection.begin();
				connection.addStatement(subject, RDFS.LABEL, F.createLiteral("two"));
				connection.rollback();
			}
			assertEquals("a rolled-back insert must not advance the stamp", afterInsert,
					(long) stamp.invoke(backingStore));
			try (SailConnection connection = store.getConnection()) {
				connection.begin();
				connection.removeStatements(subject, RDFS.LABEL, F.createLiteral("one"));
				connection.commit();
			}
			assertTrue("a removed statement must advance the stamp", (long) stamp.invoke(backingStore) > afterInsert);
		} finally {
			store.shutDown();
		}
	}

	private static boolean readLockHeldWhileParked(TxnManager txnManager) throws InterruptedException {
		for (int sample = 0; sample < 10; sample++) {
			if (!txnManager.lockManager().isReaderActive()) {
				return false;
			}
			Thread.sleep(10L);
		}
		return true;
	}

	private static void awaitLatch(CountDownLatch latch, String what) {
		try {
			if (!latch.await(20L, TimeUnit.SECONDS)) {
				throw new AssertionError("Timed out waiting for " + what);
			}
		} catch (InterruptedException e) {
			Thread.currentThread().interrupt();
			throw new AssertionError("Interrupted while waiting for " + what, e);
		}
	}

	private static void setBulkOperationSize(LmdbStoreConfig config, int bulkOperationSize) {
		try {
			Method setter = config.getClass().getMethod("setBulkOperationSize", int.class);
			setter.invoke(config, bulkOperationSize);
		} catch (ReflectiveOperationException e) {
			throw new AssertionError("Missing LMDB bulk operation size config setter", e);
		}
	}

	private Set<Statement> sampleStatements(int count) {
		Set<Statement> statements = new LinkedHashSet<>();
		for (int i = 0; i < count; i++) {
			statements.add(F.createStatement(F.createIRI("urn:bulk:subject:" + i),
					F.createIRI("urn:bulk:predicate:" + (i % 3)), F.createIRI("urn:bulk:object:" + (i % 5)),
					F.createIRI("urn:bulk:context:" + (i % 2))));
		}
		return statements;
	}

	private static long invocationCount(Object mock, String methodName) {
		return mockingDetails(mock).getInvocations()
				.stream()
				.filter(invocation -> methodName.equals(invocation.getMethod().getName()))
				.count();
	}

	private static int onlyInvocationIntArgument(Object mock, String methodName, int argumentIndex) {
		return mockingDetails(mock).getInvocations()
				.stream()
				.filter(invocation -> methodName.equals(invocation.getMethod().getName()))
				.map(invocation -> (Integer) invocation.getArgument(argumentIndex))
				.findFirst()
				.orElseThrow(() -> new AssertionError("Expected invocation of " + methodName));
	}

	private static boolean booleanField(Object target, String fieldName) throws Exception {
		Field field = target.getClass().getDeclaredField(fieldName);
		field.setAccessible(true);
		return field.getBoolean(target);
	}

	private static boolean reachesWaitState(Thread thread, long timeoutMillis) {
		long deadline = System.nanoTime() + TimeUnit.MILLISECONDS.toNanos(timeoutMillis);
		while (System.nanoTime() < deadline) {
			Thread.State state = thread.getState();
			if (state == Thread.State.WAITING || state == Thread.State.TIMED_WAITING) {
				return true;
			}
			if (!thread.isAlive()) {
				return false;
			}
			Thread.onSpinWait();
		}
		return false;
	}

	private static final class BlockingIRI extends SimpleIRI {

		private static final long serialVersionUID = 1L;

		private final AtomicBoolean armed = new AtomicBoolean();

		private final CountDownLatch entered = new CountDownLatch(1);

		private final CountDownLatch release = new CountDownLatch(1);

		private BlockingIRI(String iri) {
			super(iri);
		}

		private void arm() {
			armed.set(true);
		}

		private boolean awaitEntered() throws InterruptedException {
			return entered.await(10L, TimeUnit.SECONDS);
		}

		private void release() {
			release.countDown();
		}

		@Override
		public String getNamespace() {
			if (armed.compareAndSet(true, false)) {
				entered.countDown();
				try {
					if (!release.await(10L, TimeUnit.SECONDS)) {
						throw new AssertionError("Timed out waiting to release the blocked IRI lookup");
					}
				} catch (InterruptedException e) {
					Thread.currentThread().interrupt();
					throw new AssertionError("Interrupted while blocking the IRI lookup", e);
				}
			}
			return super.getNamespace();
		}
	}

