	@Test
	void asyncWorkerFailureReleasesQueuedBulkReservations() throws Exception {
		LmdbStore sail = new LmdbStore(new File(dataDir, "async-reservation-failure"),
				new LmdbStoreConfig("spoc,posc").setBulkOperationSize(256)
						.setSketchEstimatorEnabled(false)
						.setAutoGrow(false)
						.setValueDBSize(64L * 1024 * 1024)
						.setTripleDBSize(64L * 1024 * 1024));
		SailRepository fixture = new SailRepository(sail);
		fixture.init();
		try {
			LmdbSailStore backingStore = sail.getBackingStore();
			backingStore.enableMultiThreading = true;
			try (RepositoryConnection connection = fixture.getConnection()) {
				connection.begin(IsolationLevels.NONE);
				// Resolve this fixture's terms through real writes before its worker is held. Distinct contexts
				// keep the subsequently approved default-graph quads genuinely new without dictionary-growth drains.
				IRI seedContext = F.createIRI("urn:failure:dictionary-seed");
				for (int i = 0; i < 768; i++) {
					connection.add(F.createIRI("urn:failure:subject:" + i), F.createIRI("urn:failure:predicate"),
							F.createIRI("urn:failure:object:" + i), seedContext);
				}
				connection.commit();
			}
			Field tripleStoreField = LmdbSailStore.class.getDeclaredField("tripleStore");
			tripleStoreField.setAccessible(true);
			TripleStore originalTripleStore = (TripleStore) tripleStoreField.get(backingStore);
			TripleStore tripleStoreSpy = spy(originalTripleStore);
			CountDownLatch executing = new CountDownLatch(1);
			CountDownLatch fail = new CountDownLatch(1);
			Thread producerThread = Thread.currentThread();
			doAnswer(invocation -> {
				assertNotSame(producerThread, Thread.currentThread(),
						"the asynchronous fault must execute on the native worker");
				executing.countDown();
				if (!fail.await(1, TimeUnit.SECONDS)) {
					throw new AssertionError("Timed out waiting to fail the aligned write");
				}
				throw new IOException("expected asynchronous aligned write failure");
			}).when(tripleStoreSpy)
					.storeTriplesAligned(any(long[].class), any(long[].class), any(long[].class), any(long[].class),
							anyInt(), anyBoolean(), anyBoolean(), nullable(IntConsumer.class));
			tripleStoreField.set(backingStore, tripleStoreSpy);
			try (SailSink sink = backingStore.getExplicitSailSource().sink(IsolationLevels.NONE)) {
				for (int i = 0; i < 768; i++) {
					sink.approve(F.createIRI("urn:failure:subject:" + i), F.createIRI("urn:failure:predicate"),
							F.createIRI("urn:failure:object:" + i), null);
				}
				assertTrue(executing.await(1, TimeUnit.SECONDS));
				assertEquals(768, backingStore.reservedAlignedWriteStatements());
				fail.countDown();
				assertThrows(SailException.class, sink::flush);
				assertEquals(0, backingStore.reservedAlignedWriteStatements());
			} finally {
				fail.countDown();
				tripleStoreField.set(backingStore, originalTripleStore);
			}
		} finally {
			fixture.shutDown();
		}
	}

	@Test
	void positiveBulkOperationSizeEnablesAdaptiveBatching() throws Exception {
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,posc");
		setBulkOperationSize(config, 2);
		LmdbStore sail = new LmdbStore(new File(dataDir, "bulk-size-two"), config);
		sail.init();
		try {
			Statement seed = F.createStatement(F.createIRI("urn:adaptive-batch:seed"),
					F.createIRI("urn:adaptive-batch:predicate"), F.createLiteral("seed"));
			try (SailConnection connection = sail.getConnection()) {
				connection.begin(IsolationLevels.SNAPSHOT);
				connection.addStatement(seed.getSubject(), seed.getPredicate(), seed.getObject(), seed.getContext());
				connection.commit();
			}
			LmdbSailStore backingStore = sail.getBackingStore();
			backingStore.enableMultiThreading = false;
			Field tripleStoreField = LmdbSailStore.class.getDeclaredField("tripleStore");
			tripleStoreField.setAccessible(true);
			TripleStore originalTripleStore = (TripleStore) tripleStoreField.get(backingStore);
			TripleStore tripleStoreSpy = spy(originalTripleStore);
			tripleStoreField.set(backingStore, tripleStoreSpy);
			try (SailSink sink = backingStore.getExplicitSailSource().sink(IsolationLevels.NONE)) {
				ArgumentCaptor<long[]> subjects = ArgumentCaptor.forClass(long[].class);
				ArgumentCaptor<Integer> counts = ArgumentCaptor.forClass(Integer.class);
				clearInvocations(tripleStoreSpy);
				// A nonempty shared NONE sink buffers per-row approvals; lexical approveAll uses configured chunks.
				for (Statement statement : sampleStatements(5)) {
					sink.approve(statement.getSubject(), statement.getPredicate(), statement.getObject(),
							statement.getContext());
				}
				sink.flush();
				verify(tripleStoreSpy).storeTriplesAligned(subjects.capture(), any(long[].class), any(long[].class),
						any(long[].class), counts.capture(), anyBoolean(), anyBoolean(), nullable(IntConsumer.class));
				assertEquals(256, subjects.getValue().length);
				assertEquals(Integer.valueOf(5), counts.getValue());
				verify(tripleStoreSpy, never()).storeTriple(anyLong(), anyLong(), anyLong(), anyLong(), anyBoolean());
				Set<Statement> expected = sampleStatements(5);
				expected.add(seed);
				assertBufferedBatchStatements(backingStore, expected);
			} finally {
				tripleStoreField.set(backingStore, originalTripleStore);
			}
		} finally {
			sail.shutDown();
		}
	}

	@Test
	void compactChangesetFlushPreservesPreparedBatchAtLmdbSink() throws Exception {
		LmdbStore sail = new LmdbStore(new File(dataDir, "compact-prepared-batch"),
				new LmdbStoreConfig("spoc,posc").setBulkOperationSize(2));
		sail.init();
		SnapshotSailStore snapshotStore = null;
		try {
			LmdbSailStore backingStore = sail.getBackingStore();
			PreparedBatchRecordingSource recordingSource = new PreparedBatchRecordingSource(
					backingStore.getExplicitSailSource());
			SailStore recordingStore = new SailStore() {

				@Override
				public ValueFactory getValueFactory() {
					return backingStore.getValueFactory();
				}

				@Override
				public EvaluationStatistics getEvaluationStatistics() {
					return backingStore.getEvaluationStatistics();
				}

				@Override
				public SailSource getExplicitSailSource() {
					return recordingSource;
				}

				@Override
				public SailSource getInferredSailSource() {
					return backingStore.getInferredSailSource();
				}

				@Override
				public void close() {
					// The enclosing LmdbStore owns the backing store.
				}
			};
			snapshotStore = new SnapshotSailStore(recordingStore, LinkedHashModel::new);
			Set<Statement> statements = sampleStatements(1_024);
			try (SailSink changeset = snapshotStore.getExplicitSailSource().sink(IsolationLevels.NONE)) {
				assertEquals(statements.size(), changeset.approveAll(statements));
				changeset.flush();
			}
			snapshotStore.getExplicitSailSource().flush();
			assertEquals(1, recordingSource.approvedSetCalls);
			assertAll("the compact flush carrier should preserve and transfer its prepared batch",
					() -> assertTrue("the real Changeset flush must expose its compact prepared batch to the LMDB sink",
							recordingSource.approved instanceof Changeset.CompactApprovedSet),
					() -> {
						if (recordingSource.approved instanceof Changeset.CompactApprovedSet compact) {
							assertSame(recordingSource.preparedBatch, compact.compactStatements());
						} else {
							throw new AssertionError("the actual Changeset carrier has no prepared-batch view");
						}
					}, () -> assertThrows(UnsupportedOperationException.class,
							() -> recordingSource.preparedBatch.add(S0)));
			assertEquals(statements, recordingSource.approved);
			assertEquals(Set.of(F.createIRI("urn:bulk:context:0"), F.createIRI("urn:bulk:context:1")),
					recordingSource.approvedContexts);
			try (SailDataset dataset = backingStore.getExplicitSailSource().dataset(IsolationLevels.SNAPSHOT_READ)) {
				assertEquals(statements.size(), dataset.getStatementCount(null, null, null));
				assertEquals(statements.size() / 2,
						dataset.getStatementCount((Resource) null, null, null, F.createIRI("urn:bulk:context:0")));
			}
		} finally {
			if (snapshotStore != null) {
				snapshotStore.close();
			}
			sail.shutDown();
		}
	}

	@Test
	void ordinarySetUsesLmdbCopyFallbackAndStoresContexts() throws Exception {
		LmdbStore sail = new LmdbStore(new File(dataDir, "ordinary-set-copy-fallback"),
				new LmdbStoreConfig("spoc,posc").setBulkOperationSize(2));
		sail.init();
		try {
			LmdbSailStore backingStore = sail.getBackingStore();
			CountingStatementSet statements = new CountingStatementSet(sampleStatements(1_024));
			try (SailSink sink = backingStore.getExplicitSailSource().sink(IsolationLevels.NONE)) {
				sink.approveAll(statements,
						Set.of(F.createIRI("urn:bulk:context:0"), F.createIRI("urn:bulk:context:1")));
				sink.flush();
			}
			assertEquals("an ordinary Set must be copied once into LMDB's prepared representation", 1,
					statements.iteratorCalls);
			try (SailDataset dataset = backingStore.getExplicitSailSource().dataset(IsolationLevels.SNAPSHOT_READ)) {
				assertEquals(statements.size(), dataset.getStatementCount(null, null, null));
				assertEquals(statements.size() / 2,
						dataset.getStatementCount((Resource) null, null, null, F.createIRI("urn:bulk:context:0")));
				assertEquals(statements.size() / 2,
						dataset.getStatementCount((Resource) null, null, null, F.createIRI("urn:bulk:context:1")));
			}
		} finally {
			sail.shutDown();
		}
	}

	private static TripleStore tripleStore(LmdbSailStore backingStore) throws ReflectiveOperationException {
		Field tripleStoreField = LmdbSailStore.class.getDeclaredField("tripleStore");
		tripleStoreField.setAccessible(true);
		return (TripleStore) tripleStoreField.get(backingStore);
	}

	private static SailDataset newUntrackedDataset(LmdbSailStore backingStore, boolean explicit) throws Exception {
		// Acquire an independent paired snapshot without binding it to a connection's transaction view.
		return (explicit ? backingStore.getExplicitSailSource() : backingStore.getInferredSailSource())
				.dataset(IsolationLevels.NONE);
	}

	private static final class PreparedBatchRecordingSource extends BackingSailSource {

		private final SailSource delegate;

		private PreparedStatementBatch preparedBatch;

		private Set<Statement> approved;

		private Set<Resource> approvedContexts;

		private int approvedSetCalls;

		private PreparedBatchRecordingSource(SailSource delegate) {
			this.delegate = delegate;
		}

		@Override
		protected List<Statement> bufferStatementsForBranch(Iterable<? extends Statement> statements, int expectedSize,
				Consumer<Resource> contextConsumer) {
			preparedBatch = PreparedStatementBatch.copyOf(statements, expectedSize, contextConsumer);
			return preparedBatch;
		}

		@Override
		public SailSink sink(IsolationLevel level) throws SailException {
			return new RecordingSailSink(delegate.sink(level), this);
		}

		@Override
		public SailDataset dataset(IsolationLevel level) throws SailException {
			return delegate.dataset(level);
		}
	}

	private static final class RecordingSailSink implements SailSink {

		private final SailSink delegate;

		private final PreparedBatchRecordingSource source;

		private RecordingSailSink(SailSink delegate, PreparedBatchRecordingSource source) {
			this.delegate = delegate;
			this.source = source;
		}

		@Override
		public void close() throws SailException {
			delegate.close();
		}

		@Override
		public void prepare() throws SailException {
			delegate.prepare();
		}

		@Override
		public void flush() throws SailException {
			delegate.flush();
		}

		@Override
		public void setNamespace(String prefix, String name) throws SailException {
			delegate.setNamespace(prefix, name);
		}

		@Override
		public void removeNamespace(String prefix) throws SailException {
			delegate.removeNamespace(prefix);
		}

		@Override
		public void clearNamespaces() throws SailException {
			delegate.clearNamespaces();
		}

		@Override
		public void clear(Resource... contexts) throws SailException {
			delegate.clear(contexts);
		}

		@Override
		public void observe(Resource subj, IRI pred, Value obj, Resource... contexts) throws SailException {
			delegate.observe(subj, pred, obj, contexts);
		}

		@Override
		public void approve(Resource subj, IRI pred, Value obj, Resource ctx) throws SailException {
			delegate.approve(subj, pred, obj, ctx);
		}

		@Override
		public long approveAll(Iterable<? extends Statement> statements, Resource... contexts) throws SailException {
			return delegate.approveAll(statements, contexts);
		}

		@Override
		public void approveAll(Set<Statement> approved, Set<Resource> approvedContexts) throws SailException {
			source.approvedSetCalls++;
			source.approved = approved;
			source.approvedContexts = approvedContexts;
			delegate.approveAll(approved, approvedContexts);
		}

		@Override
		public void deprecate(Statement statement) throws SailException {
			delegate.deprecate(statement);
		}
	}

	private static final class CountingStatementSet extends LinkedHashSet<Statement> {

		private int iteratorCalls;

		private CountingStatementSet(Collection<? extends Statement> statements) {
			addAll(statements);
		}

		@Override
		public Iterator<Statement> iterator() {
			iteratorCalls++;
			return super.iterator();
		}
	}

	private void assertBufferedBatchStatements(LmdbSailStore store, Set<Statement> expected) throws Exception {
		Set<Statement> actual = new HashSet<>();
		try (SailDataset dataset = store.getExplicitSailSource().dataset(IsolationLevels.SNAPSHOT_READ);
				CloseableIteration<? extends Statement> statements = dataset.getStatements(null, null, null)) {
			while (statements.hasNext()) {
				actual.add(statements.next());
			}
		}
		assertEquals(expected, actual);
	}

	private static void assertSketchFixtureProfile(LmdbStore store) {
		try {
			assertTrue(store.getQueryExecutionPolicy().experimentalQueryOptimizations());
			assertNotNull(store.getBackingStore().getSketchBasedJoinEstimator());
		} catch (AssertionError failure) {
			try {
				store.shutDown();
			} catch (RuntimeException | Error closeFailure) {
				failure.addSuppressed(closeFailure);
			}
			throw failure;
		}
	}
